import React, { useContext } from 'react';
import { Container, Row, Col, Card } from 'react-bootstrap';
import Layout from '../common/Layout';
import { AuthContext } from '../../App';
import {
  FaUserGraduate,
  FaUserTie,
  FaBus,
  FaQuestionCircle,
  FaIdCard,
  FaCalendarAlt,
  FaUniversity,
  FaCloudSun,
} from 'react-icons/fa';
function DashBoard() {
  const { stateAuth } = useContext(AuthContext);
  const user = stateAuth?.user || {};
  const typ = (user.typ || '').toUpperCase();

  const getGreeting = () => {
    const hr = new Date().getHours();
    if (hr < 12) return 'Good Morning';
    if (hr < 17) return 'Good Afternoon';
    return 'Good Evening';
  };

  const displayName =
    user.stdnm || user.stfnm || user.drvnm || user.emlid || 'User';

  let cards = [];
  if (typ === 'STUDENT') {
    cards = [
      { label: 'Name', value: user.stdnm, icon: <FaUserGraduate /> },
      { label: 'Class', value: user.clsnm, icon: <FaUniversity /> },
      { label: 'Section', value: user.secnm, icon: <FaUniversity /> },
      { label: 'Roll Number', value: user.stdrolid, icon: <FaIdCard /> },
      { label: 'Academic Year', value: user.acdmcyr, icon: <FaCalendarAlt /> },
      { label: 'Mobile', value: user.mbleno, icon: <FaUserGraduate /> },
    ];
  } else if (typ === 'STAFF') {
    // cards = [
    //   { label: 'Name', value: user.stfnm, icon: <FaUserTie /> },
    //   { label: 'Staff ID', value: user.stfrolid, icon: <FaIdCard /> },
    //   { label: 'Academic Year', value: user.acdmcyr, icon: <FaCalendarAlt /> },
    //   { label: 'Mobile', value: user.mbleno, icon: <FaUserTie /> },
    // ];
  } else if (typ === 'TRANSPORT') {
    cards = [
      { label: 'Driver Name', value: user.drvnm, icon: <FaBus /> },
      { label: 'From Route', value: user.frrt, icon: <FaBus /> },
      { label: 'To Route', value: user.tort, icon: <FaBus /> },
      { label: 'Vehicle No', value: user.velno, icon: <FaBus /> },
      { label: 'Vehicle Type', value: user.veltyp, icon: <FaBus /> },
      { label: 'Stops', value: user.stpno, icon: <FaBus /> },
    ];
  } else {
    cards = [
      { label: 'User', value: user.emlid || user.usrid, icon: <FaQuestionCircle /> },
    ];
  }

  return (
    <Layout>
      <Container className="py-4">
        <section className="user-welcome-panel">
          <div className="user-welcome-copy">
            <h3 className="user-welcome-title">
              {getGreeting()}, {displayName}!
            </h3>
            <p className="user-welcome-subtitle">Welcome to your institute user portal.</p>
          </div>
          <div className="user-welcome-icon-wrap" aria-hidden="true">
            <div className="user-welcome-icon">
              <FaCloudSun />
            </div>
          </div>
        </section>

        <Row>
          {cards.map((c, i) => (
            <Col md={6} xl={4} key={i}>
              <Card className="mb-3 shadow-sm">
                <Card.Body className="d-flex align-items-center gap-3">
                  <div
                    className="d-flex align-items-center justify-content-center"
                    style={{
                      width: '48px',
                      height: '48px',
                      borderRadius: '12px',
                      backgroundColor: '#eff6ff',
                      color: '#2f54eb',
                    }}
                  >
                    {c.icon}
                  </div>
                  <div>
                    <div className="text-muted" style={{ fontSize: '0.78rem' }}>
                      {c.label}
                    </div>
                    <div style={{ fontWeight: 700, color: '#1e293b' }}>
                      {c.value || '—'}
                    </div>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      </Container>
    </Layout>
  );
}

export default DashBoard;
